export function SessionTimeout({
  heading = "{{heading}}",
  reason = "{{reason}}",
  secondsLeft = "{{secondsLeft}}",
  urgent = {{urgent}},
  accent = "{{accent}}",
}) {
  return (
    <div role="alertdialog" aria-label={heading}
      style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 320, padding: 20, borderRadius: 14, boxSizing: "border-box", border: `1.5px solid ${urgent ? "#D64545" : accent}` }}>
      <p style={{ margin: "0 0 6px", fontWeight: 700 }}>{heading}</p>
      <p style={{ margin: "0 0 12px", fontSize: 13, color: "#24143099" }}>You’ll be signed out {reason}.</p>
      <p style={{ margin: "0 0 16px", fontSize: 13 }}>Signing out in <strong>{secondsLeft === "30" ? "0:30" : "1:00"}</strong></p>
      <div style={{ display: "flex", gap: 10 }}>
        <button type="button" style={{ flex: 1, padding: 9, borderRadius: 8, fontWeight: 700, cursor: "pointer", font: "inherit", background: accent, border: "none", color: "#241430" }}>Stay signed in</button>
        <button type="button" style={{ flex: 1, padding: 9, borderRadius: 8, fontWeight: 700, cursor: "pointer", font: "inherit", background: "transparent", border: "1.5px solid #24143030", color: "#241430" }}>Sign out now</button>
      </div>
    </div>
  );
}
